def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)

    if not alive_opps:
        base = DAILY_SALARY * 0.35
        if hp <= 3 or no_water_days >= 1:
            base = DAILY_SALARY * 0.6
        return float(min(budget, base))

    prev_bids = []
    dangerous_bids = []
    active_count = 0
    desperate_count = 0

    for opp in alive_opps:
        if opp.get('budget', 0) > 0:
            active_count += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1

        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            prev_bids.append(float(bid))
            if opp.get('budget', 0) >= bid * 0.8:
                dangerous_bids.append(float(bid))

    top_prev = max(prev_bids) if prev_bids else DAILY_SALARY * 0.6
    top_danger = max(dangerous_bids) if dangerous_bids else top_prev
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else DAILY_SALARY * 0.6

    units = int(supply / WATER_REQ)
    contested = units <= 1

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 2

    if contested:
        urgency += 2
    if active_count >= 2:
        urgency += 1
    if desperate_count >= 1:
        urgency += 1

    if day >= 8:
        urgency += 1

    if urgency >= 6:
        bid = max(top_danger + 2.0, DAILY_SALARY * 1.42)
    elif urgency >= 4:
        bid = max(top_danger + 1.5, DAILY_SALARY * 1.34)
    elif urgency >= 2:
        bid = max(avg_prev * 0.92, top_danger - 4.0, DAILY_SALARY * 1.18)
    else:
        if units >= 2:
            bid = max(DAILY_SALARY * 0.52, avg_prev * 0.55)
        else:
            bid = max(DAILY_SALARY * 0.95, top_danger * 0.9)

    rich_rivals = 0
    for opp in alive_opps:
        if opp.get('budget', 0) >= bid:
            rich_rivals += 1
    if contested and rich_rivals >= 2 and urgency >= 3:
        bid = max(bid, top_danger + 3.0)

    if budget < DAILY_SALARY * 1.2:
        bid = min(bid, budget)
    else:
        reserve = 0.0
        if hp >= 6 and no_water_days == 0 and day <= 6:
            reserve = DAILY_SALARY * 0.15
        bid = min(bid, max(0.0, budget - reserve))

    if hp <= 2 or no_water_days >= 2:
        bid = min(budget, max(bid, DAILY_SALARY * 1.25))

    if bid < 0:
        bid = 0.0
    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        avg_prev = sum(yesterday_bids) / len(yesterday_bids)
        bid = avg_prev * 0.95
    else:
        bid = DAILY_SALARY * 0.5

    if my_status['hp'] <= 3:
        bid = min(my_status['budget'], bid * 1.5)

    return min(my_status['budget'], max(10.0, bid))
